"""Recurring nonuniform allgather compiler.

Builds weighted logical out-trees over the participant set and compressed
physical unicast routes (serial-route recipes) for the offered envelope, or
returns a checkable negative witness (deficient cut).

Model notes
-----------
* A recipe concatenation junction must not be a participant, therefore every
  emitted route walk has an interior that avoids participants entirely.  The
  compiler works on a "split" copy of the fabric in which every participant is
  duplicated into an emission half and a reception half that are not connected,
  so that any split-graph path is exactly a physical walk whose interior
  contains no participant.
* Ordinary forwarding vertices never replicate: only participants branch, which
  is expressed by the logical trees.
"""

from flow import maxflow, decompose, widest, BIG

MAX_TREES = 8192
MAX_ROUTES = 32768
MAX_RECIPE_NODES = 65536


class CompileError(Exception):
    pass


class Fabric:
    """Directed physical arcs plus the participant split graph."""

    def __init__(self, n, linkuv, cap):
        """cap: list indexed by link of the per-direction chunk capacity."""
        self.n = n
        self.linkuv = linkuv
        self.cap = cap
        self.parcs = []          # (frm, to, link, direction)
        self.pcap = []
        for l, (u, v) in enumerate(linkuv):
            c = cap[l]
            if c <= 0:
                continue
            self.parcs.append((u, v, l, 0))
            self.pcap.append(c)
            self.parcs.append((v, u, l, 1))
            self.pcap.append(c)
        self participants_fix()
        self._build_split()

    def participants_fix(self):
        pass

    def _build_split(self, participants):
        part = set(participants)
        idx = {}
        for i, v in enumerate(participants):
            idx[v] = (self.n + 2 * i, self.n + 2 * i + 1)
        self.idx = idx
        self.sarc = []
        self.s2p = []
        for i, (frm, to, l, d) in enumerate(self.parcs):
            a = idx[frm][0] if frm in part else frm
            b = idx[to][1] if to in part else to
            self.sarc.append((a, b))
            self.s2p.append(i)
        self.snodes = self.n + 2 * len(participants)
        self.sadj = [[] for _ in range(self.snodes)]
        self.eto = [0] * (2 * len(self.sarc))
        for j, (a, b) in enumerate(self.sarc):
            self.eto[2 * j] = b
            self.eto[2 * j + 1] = a
            self.sadj[a].append(2 * j)
            self.sadj[b].append(2 * j + 1)
        self.out_of = {}
        self.in_of = {}
        for v, (o, i) in idx.items():
            self.out_of[v] = o
            self.in_of[v] = i


def _route_pieces(fab, residual, x, y, need, prefer_hops):
    """Push as much as possible from participant x to participant y.

    Returns a list of (split_arc_index_list, amount) and the total pushed.
    """
    sx = fab.out_of[x]
    ty = fab.in_of[y]
    best, prev = widest([sx], fab.snodes, fab.eto, residual, fab.sadj)
    info = best[ty]
    if info is None or info[0] <= 0:
        return [], 0
    if info[0] >= need:
        seq = _trace(prev, ty)
        arcs = [seq[k] >> 1 for k in range(0, len(seq), 2)] if False else [e >> 1 for e in seq]
        return [(arcs, need)], need
    caps = [residual[2 * j] for j in range(len(fab.sarc))]
    val, fl = maxflow(fab.snodes, fab.sarc, caps, sx, ty, limit=need)
    if val <= 0:
        return [], 0
    pieces = []
    for arcs, amt in decompose(fab.snodes, fab.sarc, fl, sx, ty):
        pieces.append((arcs, amt))
    return pieces, val


def _trace(prev, target):
    seq = []
    v = target
    while prev[v] >= 0:
        e = prev[v]
        seq.append(e)
        v = e ^ 1
    seq.reverse()
    return seq


def build_plan(n, linkuv, cap, participants, demand, orders=None, deadline=None):
    """Try to compile a plan.  Returns a dict plan or None."""
    D = sum(demand[v] for v in participants)
    sources = [v for v in participants if demand[v] > 0]
    if not sources:
        return None
    fab = Fabric(n, linkuv, cap)
    fab._build_split(participants)

    if orders is None:
        orders = [
            sorted(sources, key=lambda v: (-demand[v], v)),
            sorted(sources, key=lambda v: (demand[v], v)),
            sorted(sources, key=lambda v: (demand[v], -demand[v])),
        ]
    seen = set()
    for order in orders:
        key = tuple(order)
        if key in seen:
            continue
        seen.add(key)
        plan = _attempt(fab, participants, demand, D, order)
        if plan is not None:
            return plan
    return None


class _Frag:
    __slots__ = ('nodes', 'edges', 'count')

    def __init__(self, nodes, edges, count):
        self.nodes = nodes
        self.edges = edges
        self.count = count


def _attempt(fab, participants, demand, D, order):
    residual = [0] * (2 * len(fab.sarc))
    for j in range(len(fab.sarc)):
        residual[2 * j] = fab.pcap[fab.s2p[j]]
    routes = []          # (x, y, amount, tuple_of_arc_indices)
    trees = []
    budget = [60000]

    from collections import deque
    for w in order:
        frags = deque()
        frags.append(_Frag([w], [], demand[w]))
        while frags:
            if budget[0] <= 0:
                return None
            f = frags.popleft()
            nodes = list(f.nodes)
            nodeset = set(nodes)
            edges = list(f.edges)
            count = f.count
            while len(nodeset) < len(participants):
                budget[0] -= 1
                if budget[0] <= 0:
                    return None
                sx_list = [fab.out_of[x] for x in nodeset]
                best, prev = widest(sx_list, fab.snodes, fab.eto, residual, fab.sadj)
                pick = None
                for y in participants:
                    if y in nodeset:
                        continue
                    info = best[fab.in_of[y]]
                    if info is None or info[0] <= 0:
                        continue
                    cand = (-info[0], info[1], y)
                    if pick is None or cand < pick:
                        pick = cand
                if pick is None:
                    return None
                y = pick[2]
                # starting participant
                seq = _trace(prev, fab.in_of[y])
                if not seq:
                    return None
                startnode = fab.eto[seq[0] ^ 1]
                x = None
                for cand_x in nodeset:
                    if fab.out_of[cand_x] == startnode:
                        x = cand_x
                        break
                if x is None:
                    return None
                b = -pick[0]
                need = count
                pieces = []
                if b >= need:
                    arcs = [e >> 1 for e in seq]
                    pieces = [(arcs, need)]
                    m = need
                else:
                    caps = [residual[2 * j] for j in range(len(fab.sarc))]
                    val, fl = maxflow(fab.snodes, fab.sarc, caps,
                                      fab.out_of[x], fab.in_of[y], limit=need)
                    if val <= 0:
                        return None
                    m = val
                    for arcs, amt in decompose(fab.snodes, fab.sarc, fl,
                                               fab.out_of[x], fab.in_of[y]):
                        pieces.append((arcs, amt))
                    tot = sum(a for _, a in pieces)
                    if tot != m:
                        return None
                snap_nodes = list(nodeset)
                snap_edges = list(edges)
                for arcs, amt in pieces:
                    if amt <= 0:
                        continue
                    for j in arcs:
                        residual[2 * j] -= amt
                        if residual[2 * j] < 0:
                            return None
                    phys = tuple(fab.s2p[j] for j in arcs)
                    routes.append((x, y, amt, phys))
                edges.append((x, y))
                nodeset.add(y)
                if m < count:
                    if len(frags) + len(trees) > MAX_TREES:
                        return None
                    frags.append(_Frag(snap_nodes, snap_edges, count))
                    count = m
            trees.append((w, count, edges))
            if len(trees) > MAX_TREES:
                return None
    plan = assemble(fab, trees, routes, participants, demand, D)
    return plan


# ---------------------------------------------------------------- assembly


def assemble(fab, trees, routes, participants, demand, D):
    """Aggregate routes, build recipes, and return the plan (or None)."""
    agg = {}
    for (x, y, amt, phys) in routes:
        if amt <= 0:
            return None
        key = (x, y, phys)
        agg[key] = agg.get(key, 0) + amt
    # split amounts bigger than D
    items = []
    for (x, y, phys), amt in agg.items():
        while amt > D:
            items.append((x, y, phys, D))
            amt -= D
        if amt > 0:
            items.append((x, y, phys, amt))
    if len(items) > MAX_ROUTES:
        return None

    # ---- recipes ------------------------------------------------------
    arc_key = {}
    recipes = []

    def leaf(j):
        if j in arc_key:
            return arc_key[j]
        link = fab.parcs[j][2]
        d = fab.parcs[j][3]
        rid = len(recipes)
        recipes.append([0, link, d])
        arc_key[j] = rid
        return rid

    memo = {}
    for (x, y, phys, amt) in items:
        seq = tuple(phys)
        if seq not in memo:
            chain = []
            for k in range(1, len(seq) + 1):
                pref = seq[:k]
                if pref in memo:
                    chain.append(memo[pref])
                    continue
                if k == 1:
                    rid = leaf(seq[0])
                else:
                    rid = len(recipes)
                    recipes.append([1, memo[seq[:k - 1]], leaf(seq[k - 1])])
                memo[pref] = rid
                chain.append(rid)
            memo[seq] = chain[-1]
    if len(recipes) > MAX_RECIPE_NODES:
        return None

    out_routes = []
    for (x, y, phys, amt) in items:
        out_routes.append([x, y, amt, memo[tuple(phys)]])
    out_trees = []
    for (root, count, edges) in trees:
        out_trees.append([root, count, [[u, v] for (u, v) in edges]])
    return {'trees': out_trees, 'routes': out_routes, 'recipes': recipes}


# ---------------------------------------------------------------- verification


def verify_plan(plan, n, linkuv, cap, participants, demand):
    """Exact check of a plan against the protocol.  Returns True/False."""
    D = sum(demand[v] for v in participants)
    Cset = set(participants)
    trees = plan.get('trees')
    routes = plan.get('routes')
    recipes = plan.get('recipes')
    if not isinstance(trees, list) or not isinstance(routes, list) or not isinstance(recipes, list):
        return False
    if len(trees) > MAX_TREES or len(routes) > MAX_ROUTES or len(recipes) > MAX_RECIPE_NODES:
        return False

    # ---- recipes ----
    nre = len(recipes)
    refs = [[] for _ in range(nre)]
    for node in recipes:
        if not isinstance(node, list) or len(node) != 3:
            return False
        kind = node[0]
        if kind == 0:
            l, d = node[1], node[2]
            if type(l) is not int or type(d) is not int:
                return False
            if not (0 <= l < len(linkuv)) or d not in (0, 1):
                return False
        elif kind == 1:
            a, b = node[1], node[2]
            if type(a) is not int or type(b) is not int:
                return False
            if not (0 <= a < nre) or not (0 <= b < nre):
                return False
            refs[recipes.index(node) if False else 0] = None
        else:
            return False
    # rebuild reference lists properly
    refs = [[] for _ in range(nre)]
    for i, node in enumerate(recipes):
        if node[0] == 1:
            refs[i] = [node[1], node[2]]
    # acyclicity (Kahn)
    indeg = [0] * nre
    for i in range(nre):
        for j in refs[i]:
            indeg[j] += 1
    stack = [i for i in range(nre) if indeg[i] == 0]
    order = []
    while stack:
        i = stack.pop()
        order.append(i)
        for j in refs[i]:
            indeg[j] -= 1
            if indeg[j] == 0:
                stack.append(j)
    if len(order) != nre:
        return False
    start = [None] * nre
    end = [None] * nre
    walk = [None] * nre
    for i in order:
        node = recipes[i]
        if node[0] == 0:
            l, d = node[1], node[2]
            u, v = linkuv[l]
            a, b = (u, v) if d == 0 else (v, u)
            start[i] = a
            end[i] = b
            walk[i] = [(l, d)]
        else:
            a, b = node[1], node[2]
            w = end[a]
            if w != start[b] or w in Cset:
                return False
            start[i] = start[a]
            end[i] = end[b]
            walk[i] = walk[a] + walk[b]

    # ---- routes ----
    L = {}
    for rec in routes:
        if not isinstance(rec, list) or len(rec) != 4:
            return False
        u, v, cnt, rid = rec
        if type(u) is not int or type(v) is not int or type(cnt) is not int or type(rid) is not int:
            return False
        if u not in Cset or v not in Cset or u == v:
            return False
        if not (1 <= cnt <= D):
            return False
        if not (0 <= rid < nre):
            return False
        if start[rid] != u or end[rid] != v:
            return False
        key = (u, v)
        L[key] = L.get(key, 0) + cnt

    # ---- trees ----
    per_root = {}
    for rec in trees:
        if not isinstance(rec, list) or len(rec) != 3:
            return False
        root, count, edges = rec
        if type(root) is not int or type(count) is not int or root not in Cset:
            return False
        if not (1 <= count <= D):
            return False
        if not isinstance(edges, list) or len(edges) != len(participants) - 1:
            return False
        seen_edges = set()
        indeg = {v: 0 for v in participants}
        for e in edges:
            if not isinstance(e, list) or len(e) != 2:
                return False
            u, v = e[0], e[1]
            if type(u) is not int or type(v) is not int:
                return False
            if u not in Cset or v not in Cset or u == v:
                return False
            if (u, v) in seen_edges:
                return False
            seen_edges.add((u, v))
            indeg[v] += 1
            L[(u, v)] = L.get((u, v), 0) + count
        if indeg[root] != 0:
            return False
        for v in participants:
            if v != root and indeg[v] != 1:
                return False
        # reachability from root
        adj = {}
        for (u, v) in seen_edges:
            adj.setdefault(u, []).append(v)
        st = [root]
        seen = {root}
        while st:
            u = st.pop()
            for v in adj.get(u, ()):
                if v not in seen:
                    seen.add(v)
                    st.append(v)
        if len(seen) != len(participants):
            return False
        per_root[root] = per_root.get(root, 0) + count
    for v in participants:
        if per_root.get(v, 0) != demand[v]:
            return False

    # ---- physical loads ----
    load = {}
    for rec in routes:
        u, v, cnt, rid = rec
        for (l, d) in walk[rid]:
            key = (l, d)
            load[key] = load.get(key, 0) + cnt
    for (l, d), val in load.items():
        if val > cap[l]:
            return False
    # pairs with L>0 must be fully routed (already enforced by construction of L)
    return True


# ---------------------------------------------------------------- cut witness


def find_cut(n, linkuv, linkcap, participants, demand):
    """Search a strict deficient cut.  Returns a vertex list or None."""
    D = sum(demand[v] for v in participants)
    if len(participants) < 2:
        return None
    base_nodes = n + 2
    S_node = n
    T_node = n + 1
    arcs = []
    caps = []
    for l, (u, v) in enumerate(linkuv):
        c = linkcap[l]
        if c <= 0:
            continue
        arcs.append((u, v))
        caps.append(c)
        arcs.append((v, u))
        caps.append(c)
    for w in participants:
        arcs.append((S_node, w))
        caps.append(demand[w])
    base_m = len(arcs)
    for x0 in participants:
        for y in participants:
            if x0 == y:
                continue
            a2 = arcs + [(x0, S_node), (y, T_node)]
            c2 = caps + [BIG, BIG]
            val, _fl = maxflow(base_nodes, a2, c2, S_node, T_node)
            if val >= D or val >= BIG:
                continue
            side = _min_cut_side(base_nodes, a2, c2, S_node)
            S = [v for v in side if v < n]
            inside = [v for v in S if v in set(participants)]
            outside = [v for v in participants if v not in set(S)]
            if not inside or not outside:
                continue
            capcross = 0
            sset = set(S)
            for l, (u, v) in enumerate(linkuv):
                if (u in sset) != (v in sset):
                    capcross += linkcap[l]
            rsum = sum(demand[v] for v in inside)
            if capcross < rsum:
                return S
    return None


def _min_cut_side(n, arcs, caps, s):
    m = len(arcs)
    eto = [0] * (2 * m)
    ecap = [0] * (2 * m)
    adj = [[] for _ in range(n)]
    for i, (u, v) in enumerate(arcs):
        eto[2 * i] = v
        ecap[2 * i] = caps[i]
        eto[2 * i + 1] = u
        ecap[2 * i + 1] = 0
        adj[u].append(2 * i)
        adj[v].append(2 * i + 1)
    seen = [False] * n
    seen[s] = True
    stack = [s]
    while stack:
        u = stack.pop()
        for e in adj[u]:
            if ecap[e] > 0:
                v = eto[e]
                if not seen[v]:
                    seen[v] = True
                    stack.append(v)
    return [v for v in range(n) if seen[v]]
